mapper.insert:
INSERT INTO PPM.COMM_RD_DEPARTMENT (
DEPID , LOCATION , ISDISABLED , ADMINID , REMARK ,
)VALUES(
#{depid} , #{location} , #{isdisabled} , #{adminid} , #{remark} ,
)

INSERT INTO COMM_RD_EMPLOYEE (
GENDER , UPDATEFLG , LASTUPDATEDATE , REPORTTO , ISDISABLED , SHORTPHONE , EMPNAME , EMPAUTH , BIRTHDAY , AUTHPROPERTY , REMARK , FULLNAME , JOBID , EID , BADGE , COMPID , EMPSTATUS , OFFICEPHONE , EIDHR , BOARDLINE , SPELLNAME , DEPID , HEADSHIP, MOBILETELPHONE , CERTIFICATE_TYPE , CERTIFICATE_NUMBER , NATURE , ARRIVAL_TIME ,
) VALUES(
#{gender} , #{updateflg} , #{lastupdatedate} , #{reportto} , #{isdisabled} , #{shortphone} , #{empname} , #{empauth} , #{birthday} , #{authproperty} , #{remark} , #{fullname} , #{jobid} , #{eid} , #{badge} , #{compid} , #{empstatus} , #{officephone} , #{eidhr} , #{boardline} , #{spellname} , #{depid} , #{headship} , #{mobiletelphone} , #{certificateType} , #{certificateNumber} , #{nature} , #{arrivalTime} ,
)

INSERT INTO RD_PROJECT_EMPLOYEE (
EID, PROJECT_CODE , EID_CODE ,
) VALUES(
#{eid} , #{projectCode} , #{eidCode} ,
)

INSERT INTO RD_PROJECT_ATTENDANCE_CONFIG (

    CALENDAR_DATE,

)
VALUES(

    TO_DATE(#{startDate},'yyyy-MM') ,

)

INSERT INTO COMM_RD_ATTENDANCE_AUDIT (
ID, EID, BADGE, EMPNAME, ATTENDANCE_STATUS, AUDIT_EMPLOYEE, CALENDAR_DATE,
)VALUES(
#{id}, #{eid}, #{badge}, #{username}, #{attendanceStatus}, #{auditEmployee}, TO_DATE(#{attendanceDate},'yyyy-MM'),
)

mapper.update:
UPDATE RD_PROJECT_EMPLOYEE
ISDISABLED=#{isDisabled} , PROJECT_CODE=#{projectCode} ,
WHERE PROJECT_CODE=#{projectCode} And EID=#{eid}

UPDATE PPM.COMM_RD_DEPARTMENT
LOCATION=#{chargeName} , DEPID =#{depid} ,
WHERE DEPID=#{depid}

UPDATE PPM.COMM_RD_EMPLOYEE
NATURE=#{nature} , EMPSTATUS=#{empstatus}, BADGE=#{badge}, ARRIVAL_TIME=#{arrivalTime,jdbcType=TIMESTAMP}, LEAVE_TIME=#{leaveTime,jdbcType=TIMESTAMP},
WHERE BADGE=#{badge}

UPDATE COMM_RD_ATTENDANCE_AUDIT

    ATTENDANCE_STATUS=#{attendanceStatus}

WHERE EID =#{eid}
and TO_CHAR(CALENDAR_DATE,'yyyy-MM')=#{attendanceDate}
and ATTENDANCE_STATUS in ('2' ,'3')

mapper.select:
SELECT C.EID_CODE, C.EID, C.PROJECT_CODE, E.EMPNAME, E.ARRIVAL_TIME, E.LEAVE_TIME FROM RD_PROJECT_EMPLOYEE C LEFT JOIN PPM.RD_PROJECT T ON (C.PROJECT_CODE=T.PROJECT_CODE) LEFT JOIN COMM_RD_EMPLOYEE E ON (C.EID = E.EID) WHERE T.DELETED='0' AND T.PROJECT_STATE IN ('1','2') AND C.ISDISABLED = '0'
AND (E.ARRIVAL_TIME <= #{lastDay} OR E.ARRIVAL_TIME IS NULL) AND (E.LEAVE_TIME >= #{fistDay} OR (E.LEAVE_TIME IS NULL AND E.empstatus = '0'))
AND C.EID =#{eid} AND C.PROJECT_CODE =#{projectCode} AND C.EID_CODE =#{eidCode}

mapper.delete:
delete from RD_PROJECT_CONFIG G
where g.eid_code =#{eidCode}
and to_char(g.calendar_date,'yyyy-MM')=#{attendanceDate}

mapper.select:
SELECT C.EMPNAME USERNAME, C.BADGE, C.NATURE, D.LOCATION CHARGENAME, E.EID_CODE, T.PROJECT_CODE, (SELECT SUM(BUDGET_AMOUNT) FROM RD_PROJECT_CONTRACT R WHERE T.PK_ID=R.RD_PROJECT_ID) BUDGET_AMOUNT, T.PROJECT_NAME, T.PROJECT_STATE, ROUND(( (SELECT SUM(ABS(g.attendance_time)) FROM PPM.RD_PROJECT_CONFIG g WHERE G.EID_CODE =E.EID_CODE AND G.ATTENDANCE_ORNO = '1' AND G.IS_HOLIDAY = 'N' AND TO_CHAR(g.calendar_date,'yyyy-MM')=#{attendanceDate} )/ (SELECT COUNT(G.CALENDAR_DATE) FROM PPM.RD_PROJECT_CONFIG g WHERE TO_CHAR(g.calendar_date,'yyyy-MM')=#{attendanceDate} AND G.EID_CODE =E.EID_CODE AND G.ATTENDANCE_ORNO = '1' AND G.IS_HOLIDAY = 'N' ) ) ,4) PROPORTION FROM PPM.COMM_RD_EMPLOYEE C LEFT JOIN COMM_RD_DEPARTMENT D ON C.DEPID = D.DEPID LEFT JOIN (SELECT EID_CODE,PROJECT_CODE,EID,ISDISABLED ,CREATE_DATE FROM PPM.RD_PROJECT_EMPLOYEE WHERE ISDISABLED='0') E ON C.EID = E.EID LEFT JOIN PPM.RD_PROJECT T ON E.PROJECT_CODE = T.PROJECT_CODE WHERE T.PROJECT_STATE IN ('1', '2') AND T.DELETED = '0' AND C.DEPID = #{depid}
AND C.BADGE IN
#{item}
AND (c.ARRIVAL_TIME <= #{lastDay} or c.ARRIVAL_TIME is null) and (c.LEAVE_TIME > #{firstDay} or (c.LEAVE_TIME is null and c.empstatus = '0'))
ORDER BY CASE C.BADGE
WHEN #{item} THEN #{index}
END, T.PROJECT_CODE
